#!/usr/bin/env node
// Build-time export of a pinned specialist bundle (contract section 5).
//
//   node specialist-runtime/tools/export-bundle.mjs \
//     --kb-checkout /path/to/Epinoic-Agent-Training \
//     --commit <40-hex commit> \
//     --slug history \
//     --bundle-path <path of the bundle inside the checkout> \
//     --out specialist-runtime/dist/history.bundle.mjs \
//     [--kb-version <version>]
//
// Refuses (exit 1, nothing written) unless ALL of these hold:
//   - the slug has an entry in RUNTIME_MANIFEST (src/manifest.js);
//   - --commit is a full 40-hex id, and equals the manifest's pinned commit if one is set;
//   - --bundle-path is a safe relative path, and equals the manifest's pinned path if set;
//   - --kb-version (optional) equals the manifest's kbVersion if set; when omitted the
//     manifest value is used (null while pending);
//   - --kb-checkout is the top level of a git work tree whose HEAD equals --commit
//     (`git -C <checkout> rev-parse HEAD`);
//   - the bundle path is tracked at HEAD and has no uncommitted or untracked changes
//     (`git status --porcelain -- <path>` is empty), is a regular file (not a symlink),
//     and its working-tree bytes equal the committed blob bytes;
//   - SHA-256 of those exact bytes equals the manifest's bundleSha256;
//   - the bytes are valid UTF-8;
//   - --out ends in .mjs, is outside the checkout, and, if it is inside any git work
//     tree, is git-ignored (the bundle is proprietary; this repository is public).
// There is no bypass flag. Usage errors exit 2.
//
// The written module embeds the exact file bytes (base64), so BOM and line
// endings survive; loadPinnedBundle re-verifies them at runtime.

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, lstatSync, mkdirSync, readFileSync, realpathSync, renameSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { RUNTIME_MANIFEST, checkManifest } from "../src/manifest.js";
import { UsageError, parseStrictArgs } from "./lib/args.mjs";

export class ExportRefusal extends Error {
  /**
   * @param {string} code
   * @param {string} message
   */
  constructor(code, message) {
    super(`${code}: ${message}`);
    this.name = "ExportRefusal";
    this.code = code;
  }
}

const COMMIT = /^[0-9a-f]{40}$/;

function gitEnv() {
  const env = {};
  for (const [k, v] of Object.entries(process.env)) if (!k.startsWith("GIT_")) env[k] = v;
  env.GIT_CONFIG_NOSYSTEM = "1";
  env.GIT_TERMINAL_PROMPT = "0";
  return env;
}

/** Run git; returns { ok, stdout (Buffer) }. */
function git(cwd, args) {
  try {
    const stdout = execFileSync("git", ["-C", cwd, ...args], { env: gitEnv(), stdio: ["ignore", "pipe", "pipe"], maxBuffer: 256 * 1024 * 1024 });
    return { ok: true, stdout };
  } catch {
    return { ok: false, stdout: Buffer.alloc(0) };
  }
}

function isSafeRelativePath(p) {
  if (typeof p !== "string" || p.length === 0 || isAbsolute(p) || p.includes("\\") || p.includes("\0")) return false;
  return p.split("/").every((seg) => seg.length > 0 && seg !== "." && seg !== "..");
}

function isInside(child, parent) {
  return child === parent || child.startsWith(parent + sep);
}

function manifestOk(manifest) {
  return checkManifest(manifest, "runtime").ok || checkManifest(manifest, "offline-test").ok;
}

/**
 * Render the bundle module source.
 * @param {object} fields
 */
export function renderModule(fields) {
  const body = [
    ["schema", "epinoic.specialist-bundle-module.v1"],
    ["slug", fields.slug],
    ["sourceRepo", fields.sourceRepo],
    ["sourceCommit", fields.sourceCommit],
    ["bundlePath", fields.bundlePath],
    ["kbVersion", fields.kbVersion],
    ["sha256", fields.sha256],
    ["byteLength", fields.byteLength],
    ["base64", fields.base64],
  ]
    .map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`)
    .join(",\n");
  return (
    "// Generated by specialist-runtime/tools/export-bundle.mjs. Do not edit.\n" +
    "// Contains proprietary knowledge-base bytes: never commit this file.\n" +
    `export const BUNDLE = Object.freeze({\n${body}\n});\n`
  );
}

/**
 * Export a bundle module. Throws ExportRefusal on any failed condition.
 * `manifest` defaults to the pinned RUNTIME_MANIFEST; the CLI cannot change it
 * (tests inject a synthetic manifest through this function only).
 * @param {{ kbCheckout: string, commit: string, slug: string, bundlePath: string, out: string,
 *   kbVersion?: string, manifest?: object }} options
 */
export function exportBundle({ kbCheckout, commit, slug, bundlePath, out, kbVersion, manifest = RUNTIME_MANIFEST }) {
  if (!manifestOk(manifest)) throw new ExportRefusal("manifest_invalid", "the manifest fails validation");
  const entry = manifest.entries.find((e) => e.slug === slug);
  if (!entry) throw new ExportRefusal("unknown_slug", `no manifest entry for slug "${slug}"`);
  if (!COMMIT.test(commit)) throw new ExportRefusal("commit_invalid", "--commit must be a full 40-hex lowercase commit id");
  if (entry.source.commit !== null && entry.source.commit !== commit) {
    throw new ExportRefusal("commit_not_pinned", "--commit differs from the manifest's pinned commit");
  }
  if (!isSafeRelativePath(bundlePath)) throw new ExportRefusal("bundle_path_invalid", "--bundle-path must be a relative path without . or .. segments");
  if (entry.source.bundlePath !== null && entry.source.bundlePath !== bundlePath) {
    throw new ExportRefusal("bundle_path_not_pinned", "--bundle-path differs from the manifest's pinned bundle path");
  }
  if (kbVersion !== undefined && entry.kbVersion !== null && kbVersion !== entry.kbVersion) {
    throw new ExportRefusal("kb_version_not_pinned", "--kb-version differs from the manifest's kbVersion");
  }
  const moduleKbVersion = kbVersion ?? entry.kbVersion;

  if (!existsSync(kbCheckout)) throw new ExportRefusal("checkout_missing", "--kb-checkout does not exist");
  const checkout = realpathSync(kbCheckout);
  const top = git(checkout, ["rev-parse", "--show-toplevel"]);
  if (!top.ok || realpathSync(top.stdout.toString("utf8").trim()) !== checkout) {
    throw new ExportRefusal("checkout_not_git_toplevel", "--kb-checkout must be the top level of a git work tree");
  }
  const head = git(checkout, ["rev-parse", "HEAD"]);
  if (!head.ok || head.stdout.toString("utf8").trim() !== commit) {
    throw new ExportRefusal("head_mismatch", "HEAD of the checkout does not equal --commit");
  }
  if (!git(checkout, ["ls-files", "--error-unmatch", "--", bundlePath]).ok) {
    throw new ExportRefusal("bundle_path_untracked", "the bundle path is not tracked in the checkout");
  }
  const status = git(checkout, ["status", "--porcelain", "--untracked-files=all", "--", bundlePath]);
  if (!status.ok || status.stdout.length > 0) {
    throw new ExportRefusal("bundle_path_dirty", "the bundle path has uncommitted or untracked changes");
  }
  const filePath = resolve(checkout, bundlePath);
  if (!isInside(filePath, checkout) || !existsSync(filePath) || !lstatSync(filePath).isFile()) {
    throw new ExportRefusal("bundle_not_regular_file", "the bundle path is not a regular file inside the checkout");
  }
  const bytes = readFileSync(filePath);
  const blob = git(checkout, ["cat-file", "blob", `${commit}:${bundlePath}`]);
  if (!blob.ok || !blob.stdout.equals(bytes)) {
    throw new ExportRefusal("worktree_differs_from_commit", "working-tree bytes differ from the committed blob");
  }
  if (bytes.length === 0) throw new ExportRefusal("bundle_empty", "the bundle file is empty");
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  if (sha256 !== entry.bundleSha256) {
    throw new ExportRefusal("sha256_mismatch", `SHA-256 ${sha256} differs from the manifest's ${entry.bundleSha256}`);
  }
  try {
    new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    throw new ExportRefusal("invalid_utf8", "the bundle is not valid UTF-8");
  }

  const outPath = resolve(out);
  if (!outPath.endsWith(".mjs")) throw new ExportRefusal("out_path_invalid", "--out must end in .mjs");
  if (isInside(outPath, checkout)) throw new ExportRefusal("out_path_inside_checkout", "--out must be outside the knowledge-base checkout");
  const outDir = dirname(outPath);
  let probe = outDir;
  while (!existsSync(probe)) probe = dirname(probe);
  const inTree = git(probe, ["rev-parse", "--is-inside-work-tree"]);
  if (inTree.ok && inTree.stdout.toString("utf8").trim() === "true" && !git(probe, ["check-ignore", "-q", "--", outPath]).ok) {
    throw new ExportRefusal("out_path_not_ignored", "--out is inside a git work tree but not git-ignored");
  }
  mkdirSync(outDir, { recursive: true });

  const source = renderModule({
    slug,
    sourceRepo: entry.source.repo,
    sourceCommit: commit,
    bundlePath,
    kbVersion: moduleKbVersion,
    sha256,
    byteLength: bytes.length,
    base64: bytes.toString("base64"),
  });
  const tmp = `${outPath}.tmp`;
  writeFileSync(tmp, source);
  renameSync(tmp, outPath);
  return {
    slug,
    out: outPath,
    sha256,
    byteLength: bytes.length,
    sourceRepo: entry.source.repo,
    sourceCommit: commit,
    bundlePath,
    kbVersion: moduleKbVersion,
    manifestSha256Status: entry.bundleSha256Status,
  };
}

const USAGE =
  "usage: node tools/export-bundle.mjs --kb-checkout <dir> --commit <40-hex> --slug <slug> " +
  "--bundle-path <relative path> --out <file.mjs> [--kb-version <version>]\n";

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  try {
    const args = parseStrictArgs(process.argv.slice(2), {
      required: ["kb-checkout", "commit", "slug", "bundle-path", "out"],
      optional: ["kb-version"],
    });
    const result = exportBundle({
      kbCheckout: args["kb-checkout"],
      commit: args.commit,
      slug: args.slug,
      bundlePath: args["bundle-path"],
      out: args.out,
      kbVersion: args["kb-version"],
    });
    process.stdout.write(`${JSON.stringify({ exported: true, ...result }, null, 2)}\n`);
    process.stdout.write(
      "The SHA-256 matches the manifest. Record the pins (commit, bundlePath, kbVersion) and " +
        "bundleSha256Status \"verified\" only through a reviewed change.\n",
    );
  } catch (err) {
    if (err instanceof UsageError) {
      process.stderr.write(`export-bundle: ${err.message}\n${USAGE}`);
      process.exit(2);
    }
    if (err instanceof ExportRefusal) {
      process.stderr.write(`export-bundle: refused: ${err.message}\n`);
      process.exit(1);
    }
    throw err;
  }
}
